class Solution {
public:
    vector<string> alertNames(vector<string>& keyName, vector<string>& keyTime) {
        unordered_map<string, vector<int>> uses;
        for (int i = 0; i < (int)keyName.size(); ++i) {
            int m = stoi(keyTime[i].substr(0, 2)) * 60 + stoi(keyTime[i].substr(3));
            uses[keyName[i]].push_back(m);
        }
        vector<string> res;
        for (auto& [name, ts] : uses) {
            sort(ts.begin(), ts.end());
            for (int i = 0; i < (int)ts.size(); ++i) {
                int cnt = 0;
                for (int j = i; j < (int)ts.size(); ++j) {
                    if (ts[j] - ts[i] > 60) break;
                    ++cnt;
                }
                if (cnt >= 3) { res.push_back(name); break; }
            }
        }
        sort(res.begin(), res.end());
        return res;
    }
};

