class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<Integer>> uses = new HashMap<>();
        for (int i = 0; i < keyName.length; i++) {
            int m = Integer.parseInt(keyTime[i].substring(0, 2)) * 60
                  + Integer.parseInt(keyTime[i].substring(3));
            uses.computeIfAbsent(keyName[i], k -> new ArrayList<>()).add(m);
        }
        List<String> res = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> e : uses.entrySet()) {
            List<Integer> ts = e.getValue();
            Collections.sort(ts);
            for (int i = 0; i < ts.size(); i++) {
                int cnt = 0;
                for (int j = i; j < ts.size(); j++) {
                    if (ts.get(j) - ts.get(i) > 60) break;
                    cnt++;
                }
                if (cnt >= 3) {
                    res.add(e.getKey());
                    break;
                }
            }
        }
        Collections.sort(res);
        return res;
    }
}

